describe('MCP tool catalog', () => {
	it('creates one curated tool per discriminated request variant', () => {
		const tools = getCuratedTools();

		expect(tools.map(({ name }) => name)).toEqual([
			'post_chat_postMessage_by_roomId',
			'post_chat_postMessage_by_channel',
			'post_channels_create',
			'get_channels_list_joined',
			'get_rooms_get',
		]);
		expect(tools[0]?.inputSchema).toEqual({
			type: 'object',
			description: 'Post by room id',
			properties: { roomId: { type: 'string' }, text: { type: 'string' } },
			required: ['roomId'],
		});
		expect(tools[4]?.inputSchema).toMatchObject({ additionalProperties: { type: 'string' } });
	});

	it('only exposes allow-listed routes in the extended catalog', () => {
		const tools = getExtendedTools();

		expect(tools.map(({ name }) => name)).toEqual(
			expect.arrayContaining([
				'post_chat_postMessage_by_roomId',
				'post_chat_postMessage_by_channel',
				'post_channels_create',
				'get_channels_list_joined',
				'get_rooms_get',
				'get_rooms_isMember_by_roomId_userId',
				'get_rooms_isMember_by_roomId_username',
			]),
		);
		expect(tools.some(({ name }) => name.includes('users_delete'))).toBe(false);
		expect(tools.some(({ name }) => name.includes('users_register'))).toBe(false);
	});

	it('keeps curated tool names stable when the extended catalog is enabled', () => {
		const extendedNames = new Set(getExtendedTools().map(({ name }) => name));

		expect(getCuratedTools().every(({ name }) => extendedNames.has(name))).toBe(true);
	});

	it('generates unique valid names when variant discriminators exceed the MCP limit', () => {
		const tools = getExtendedTools();
		const names = tools.map(({ name }) => name);
		const dmFileNames = tools.filter(({ path }) => path === '/api/v1/dm.files').map(({ name }) => name);

		expect(dmFileNames).toHaveLength(2);
		expect(new Set(names).size).toBe(names.length);
		expect(names.every((name) => name.length <= 64 && /^[a-zA-Z0-9_-]+$/.test(name))).toBe(true);
	});

	it('preserves parent properties when variants only declare required fields', () => {
		const tools = getExtendedTools().filter(({ name }) => name.startsWith('get_rooms_isMember'));

		for (const { inputSchema } of tools) {
			const properties = inputSchema.properties as Record<string, unknown>;
			for (const requiredProperty of inputSchema.required as string[]) {
				expect(properties).toHaveProperty(requiredProperty);
			}
		}
	});

	it('preserves shared required fields without changing variant discriminators', () => {
		const tools = getExtendedTools().filter(({ name }) => name.startsWith('get_teams_listRoomsOfUser'));

		expect(tools.map(({ name }) => name)).toEqual(['get_teams_listRoomsOfUser_by_teamId', 'get_teams_listRoomsOfUser_by_teamName']);
		for (const { inputSchema } of tools) {
			expect(inputSchema.required).toEqual(expect.arrayContaining(['userId']));
		}
	});

	it('reuses the generated catalogs between requests', () => {
		expect(getCuratedTools()).toBe(getCuratedTools());
		expect(getExtendedTools()).toBe(getExtendedTools());
	});
});

import { createMcpResponseBudget, dispatchTool } from './dispatch';
import type { McpAuth } from './server';

const auth: McpAuth = {
	userId: 'user-id',
	authToken: '<REDACTED>',
};

describe('MCP tool dispatch', () => {
	const originalPort = process.env.PORT;
	const runtimeGlobal = globalThis as typeof globalThis & { __meteor_runtime_config__?: { ROOT_URL_PATH_PREFIX?: string } };
	const originalRuntimeConfig = runtimeGlobal.__meteor_runtime_config__;

	afterEach(() => {
		jest.restoreAllMocks();
		if (originalPort === undefined) {
			delete process.env.PORT;
		} else {
			process.env.PORT = originalPort;
		}
		if (originalRuntimeConfig === undefined) {
			delete runtimeGlobal.__meteor_runtime_config__;
		} else {
			runtimeGlobal.__meteor_runtime_config__ = originalRuntimeConfig;
		}
	});

	it('forwards GET arguments and caller identity to the local REST API', async () => {
		process.env.PORT = '3100';
		runtimeGlobal.__meteor_runtime_config__ = { ROOT_URL_PATH_PREFIX: '/chat' };
		const fetchMock = jest
			.spyOn(global, 'fetch')
			.mockResolvedValue(new Response(JSON.stringify({ message: { _id: 'message-id' } }), { status: 200 }));

		const result = await dispatchTool(
			{
				name: 'chat_getMessage',
				description: 'Get a message',
				inputSchema: { type: 'object' },
				path: '/api/v1/chat.getMessage',
				method: 'get',
			},
			{ msgId: 'message-id', fields: { msg: 1 }, optional: undefined },
			auth,
			'192.0.2.1',
		);

		expect(fetchMock).toHaveBeenCalledWith(
			'http://127.0.0.1:3100/chat/api/v1/chat.getMessage?msgId=message-id&fields=%7B%22msg%22%3A1%7D',
			expect.objectContaining({
				method: 'GET',
				redirect: 'error',
				headers: {
					'Content-Type': 'application/json',
					'X-User-Id': 'user-id',
					'X-Auth-Token': 'auth-token',
					'X-Real-IP': '192.0.2.1',
				},
				signal: expect.any(AbortSignal),
			}),
		);
		expect(result).toEqual({ ok: true, status: 200, body: { message: { _id: 'message-id' } } });
	});

	it('preserves non-JSON error responses', async () => {
		jest.spyOn(global, 'fetch').mockResolvedValue(new Response('Service unavailable', { status: 503 }));

		await expect(
			dispatchTool(
				{
					name: 'chat_postMessage',
					description: 'Post a message',
					inputSchema: { type: 'object' },
					path: '/api/v1/chat.postMessage',
					method: 'post',
				},
				{ roomId: 'room-id', text: 'Hello' },
				auth,
			),
		).resolves.toEqual({ ok: false, status: 503, body: 'Service unavailable' });
	});

	it('handles empty REST responses', async () => {
		jest.spyOn(global, 'fetch').mockResolvedValue(new Response(null, { status: 204 }));

		await expect(
			dispatchTool(
				{
					name: 'subscriptions_read',
					description: 'Mark a subscription as read',
					inputSchema: { type: 'object' },
					path: '/api/v1/subscriptions.read',
					method: 'post',
				},
				{ rid: 'room-id' },
				auth,
			),
		).resolves.toEqual({ ok: true, status: 204, body: '' });
	});

	it('rejects responses whose content length exceeds the MCP result size limit', async () => {
		jest.spyOn(global, 'fetch').mockResolvedValue(
			new Response(null, {
				status: 200,
				headers: { 'content-length': String(5 * 1024 * 1024 + 1) },
			}),
		);

		await expect(
			dispatchTool(
				{
					name: 'rooms_get',
					description: 'Get rooms',
					inputSchema: { type: 'object' },
					path: '/api/v1/rooms.get',
					method: 'get',
				},
				{},
				auth,
			),
		).rejects.toThrow('MCP tool response exceeds the 5 MiB limit');
	});

	it('stops streaming responses that exceed the MCP result size limit', async () => {
		jest.spyOn(global, 'fetch').mockResolvedValue(new Response(new Uint8Array(5 * 1024 * 1024 + 1), { status: 200 }));

		await expect(
			dispatchTool(
				{
					name: 'rooms_get',
					description: 'Get rooms',
					inputSchema: { type: 'object' },
					path: '/api/v1/rooms.get',
					method: 'get',
				},
				{},
				auth,
			),
		).rejects.toThrow('MCP tool response exceeds the 5 MiB limit');
	});

	it('shares the response size budget across batched tool calls', async () => {
		jest.spyOn(global, 'fetch').mockImplementation(async () => new Response('abc', { status: 200 }));
		const responseBudget = createMcpResponseBudget(5);
		const tool = {
			name: 'rooms_get',
			description: 'Get rooms',
			inputSchema: { type: 'object' },
			path: '/api/v1/rooms.get',
			method: 'get' as const,
		};

		await expect(dispatchTool(tool, {}, auth, undefined, responseBudget)).resolves.toMatchObject({ body: 'abc' });
		await expect(dispatchTool(tool, {}, auth, undefined, responseBudget)).rejects.toThrow('MCP batch response exceeds the 5 bytes limit');
	});
});

import { getCuratedTools, getExtendedTools } from './catalog';
import { dispatchTool } from './dispatch';
import { handleRpcMessage, isJsonRpcRequest, type McpAuth } from './server';
import { settings } from '../../../../server/settings/cached';

jest.mock('./catalog', () => ({
	getCuratedTools: jest.fn(),
	getExtendedTools: jest.fn(),
}));

jest.mock('./dispatch', () => ({
	dispatchTool: jest.fn(),
}));

jest.mock('../../../../server/api/lib/getTrimmedServerVersion', () => ({
	getTrimmedServerVersion: () => '9.0',
}));

jest.mock('../../../../server/settings/cached', () => ({
	settings: { get: jest.fn() },
}));

const auth: McpAuth = {
	userId: 'user-id',
	authToken: '<REDACTED>',
};

const tool = {
	name: 'get_chat_getMessage',
	description: 'Get a message',
	inputSchema: { type: 'object' },
	path: '/api/v1/chat.getMessage',
	method: 'get' as const,
};

const extendedTool = {
	...tool,
	name: 'get_chat_search',
	description: 'Search messages',
	path: '/api/v1/chat.search',
};

const initializeParams = {
	protocolVersion: '2025-06-18',
	capabilities: {},
	clientInfo: { name: 'test-client', version: '1.0.0' },
};

describe('MCP JSON-RPC server', () => {
	beforeEach(() => {
		jest.mocked(settings.get).mockReturnValue(false);
		jest.mocked(getCuratedTools).mockReset().mockReturnValue([tool]);
		jest.mocked(getExtendedTools).mockReset().mockReturnValue([]);
		jest.mocked(dispatchTool).mockReset();
	});

	it('rejects malformed JSON-RPC messages without throwing', async () => {
		expect(isJsonRpcRequest({ jsonrpc: '2.0', method: 'ping' })).toBe(true);
		expect(isJsonRpcRequest({ jsonrpc: '1.0', method: 'ping' })).toBe(false);
		expect(isJsonRpcRequest({ jsonrpc: '2.0', id: null, method: 'ping' })).toBe(false);

		await expect(handleRpcMessage(null, auth)).resolves.toEqual({
			jsonrpc: '2.0',
			id: null,
			error: { code: -32600, message: 'Invalid Request' },
		});
	});

	it('returns server capabilities during initialization', async () => {
		await expect(handleRpcMessage({ jsonrpc: '2.0', id: 1, method: 'initialize', params: initializeParams }, auth)).resolves.toEqual({
			jsonrpc: '2.0',
			id: 1,
			result: {
				protocolVersion: '2025-06-18',
				capabilities: { tools: { listChanged: false } },
				serverInfo: { name: 'rocketchat', version: '9.0' },
			},
		});
	});

	it('falls back to the latest supported version when negotiation fails', async () => {
		await expect(
			handleRpcMessage(
				{
					jsonrpc: '2.0',
					id: 2,
					method: 'initialize',
					params: { ...initializeParams, protocolVersion: 'unsupported' },
				},
				auth,
			),
		).resolves.toMatchObject({ result: { protocolVersion: '2025-11-25' } });
	});

	it('rejects initialize requests without the required client information', async () => {
		await expect(
			handleRpcMessage({ jsonrpc: '2.0', id: 2, method: 'initialize', params: { protocolVersion: '2025-11-25' } }, auth),
		).resolves.toMatchObject({ error: { code: -32602, message: 'Invalid initialize parameters' } });
	});

	it('lists the curated toolset by default', async () => {
		const response = await handleRpcMessage({ jsonrpc: '2.0', id: 3, method: 'tools/list' }, auth);

		expect(getCuratedTools).toHaveBeenCalledTimes(1);
		expect(getExtendedTools).not.toHaveBeenCalled();
		expect(response).toMatchObject({ result: { tools: [{ name: tool.name }] } });
	});

	it('lists the extended toolset when enabled', async () => {
		jest.mocked(settings.get).mockReturnValue(true);
		jest.mocked(getExtendedTools).mockReturnValue([extendedTool]);

		const response = await handleRpcMessage({ jsonrpc: '2.0', id: 3, method: 'tools/list' }, auth);

		expect(getExtendedTools).toHaveBeenCalledTimes(1);
		expect(getCuratedTools).not.toHaveBeenCalled();
		expect(response).toMatchObject({ result: { tools: [{ name: extendedTool.name }] } });
	});

	it('validates tool call parameters before dispatch', async () => {
		await expect(
			handleRpcMessage({ jsonrpc: '2.0', id: 3, method: 'tools/call', params: { name: tool.name, arguments: [] } }, auth),
		).resolves.toMatchObject({ error: { code: -32602 } });
		expect(dispatchTool).not.toHaveBeenCalled();
	});

	it('dispatches a known tool as the authenticated user', async () => {
		jest.mocked(dispatchTool).mockResolvedValue({ ok: true, status: 200, body: { message: { _id: 'message-id' } } });

		const response = await handleRpcMessage(
			{ jsonrpc: '2.0', id: 4, method: 'tools/call', params: { name: tool.name, arguments: { msgId: 'message-id' } } },
			auth,
			'192.0.2.1',
		);

		expect(dispatchTool).toHaveBeenCalledWith(tool, { msgId: 'message-id' }, auth, '192.0.2.1', undefined);
		expect(response).toEqual({
			jsonrpc: '2.0',
			id: 4,
			result: {
				content: [{ type: 'text', text: JSON.stringify({ message: { _id: 'message-id' } }) }],
				isError: false,
			},
		});
	});

	it('marks unsuccessful REST responses as tool errors', async () => {
		jest.mocked(dispatchTool).mockResolvedValue({ ok: false, status: 403, body: { error: 'Forbidden' } });

		await expect(
			handleRpcMessage({ jsonrpc: '2.0', id: 5, method: 'tools/call', params: { name: tool.name, arguments: {} } }, auth),
		).resolves.toMatchObject({ result: { isError: true, content: [{ text: JSON.stringify({ error: 'Forbidden' }) }] } });
	});

	it('returns thrown dispatch failures as tool errors', async () => {
		jest.mocked(dispatchTool).mockRejectedValue(new Error('Connection failed'));

		await expect(
			handleRpcMessage({ jsonrpc: '2.0', id: 6, method: 'tools/call', params: { name: tool.name, arguments: {} } }, auth),
		).resolves.toMatchObject({ result: { isError: true, content: [{ text: 'Tool execution failed: Connection failed' }] } });
	});

	it('rejects unknown tools without dispatching', async () => {
		await expect(
			handleRpcMessage({ jsonrpc: '2.0', id: 5, method: 'tools/call', params: { name: 'unknown', arguments: {} } }, auth),
		).resolves.toMatchObject({ error: { code: -32602, message: 'Unknown tool: unknown' } });
